using Mono.Cecil;using Mono.Cecil.Cil;using System.Security.Cryptography;using System.Text.Json;
string original=args[0],candidate=args[1],game=args[2],output=args[3];
using var resolver=new DefaultAssemblyResolver();foreach(string dir in new[]{Path.Combine(game,"CharaStudio_Data/Managed"),Path.Combine(game,"BepInEx/core"),Path.Combine(game,"BepInEx/plugins/KKS_BepisPlugins")})resolver.AddSearchDirectory(dir);
var rp=new ReaderParameters{AssemblyResolver=resolver};using var a=AssemblyDefinition.ReadAssembly(original,rp);using var b=AssemblyDefinition.ReadAssembly(candidate,rp);
IEnumerable<TypeDefinition> Types(IEnumerable<TypeDefinition> types){foreach(var t in types){yield return t;foreach(var n in Types(t.NestedTypes))yield return n;}}
string Operand(object o,IList<Instruction> body)=>o switch{null=>"",Instruction i=>"#"+body.IndexOf(i),Instruction[] set=>string.Join(",",set.Select(x=>"#"+body.IndexOf(x))),_=>o.ToString()};
string Shape(MethodDefinition m)=>!m.HasBody?"none":m.Body.InitLocals+"/"+string.Join("|",m.Body.Variables.Select(v=>v.VariableType.FullName))+"/"+string.Join("\n",m.Body.Instructions.Select(i=>i.OpCode.Name+" "+Operand(i.Operand,m.Body.Instructions)))+"/"+string.Join("|",m.Body.ExceptionHandlers.Select(e=>e.HandlerType+":"+e.CatchType?.FullName+":"+m.Body.Instructions.IndexOf(e.TryStart)+":"+m.Body.Instructions.IndexOf(e.TryEnd)+":"+m.Body.Instructions.IndexOf(e.HandlerStart)+":"+m.Body.Instructions.IndexOf(e.HandlerEnd)));
var old=Types(a.MainModule.Types).SelectMany(t=>t.Methods).ToDictionary(m=>m.FullName);var current=Types(b.MainModule.Types).SelectMany(t=>t.Methods).ToDictionary(m=>m.FullName);
var changed=old.Keys.Where(k=>!current.ContainsKey(k)||Shape(old[k])!=Shape(current[k])).ToArray();
bool lifecycle=b.MainModule.GetType("CameraFXSlotsRepair.SlotLifecycle")!=null;
var expectedChanges=lifecycle?new[]{"HookExtendedSaveEvents","UnhookExtendedSaveEvents","Update","InitializeUI","AddButtonsForNewSlots","Cleanup"}:new[]{"HookExtendedSaveEvents","UnhookExtendedSaveEvents"};
var addedMethods=current.Keys.Except(old.Keys).ToArray();
bool scope=old.Keys.All(current.ContainsKey)&&changed.Length==expectedChanges.Length&&changed.All(k=>expectedChanges.Contains(old[k].Name))&&addedMethods.All(k=>current[k].DeclaringType.Namespace=="CameraFXSlotsRepair");
string[] originalFields=Types(a.MainModule.Types).SelectMany(t=>t.Fields).Select(f=>f.FullName+" "+f.Attributes).ToArray(),newFields=Types(b.MainModule.Types).Where(t=>t.Namespace!="CameraFXSlotsRepair").SelectMany(t=>t.Fields).Select(f=>f.FullName+" "+f.Attributes).ToArray();
string Resource(Resource r)=>r is EmbeddedResource e?r.Name+":"+Convert.ToHexString(SHA256.HashData(e.GetResourceData())):r.Name;
bool resources=a.MainModule.Resources.Select(Resource).SequenceEqual(b.MainModule.Resources.Select(Resource));
var removed=a.MainModule.AssemblyReferences.Select(r=>r.FullName).Except(b.MainModule.AssemblyReferences.Select(r=>r.FullName)).ToArray();var added=b.MainModule.AssemblyReferences.Select(r=>r.FullName).Except(a.MainModule.AssemblyReferences.Select(r=>r.FullName)).ToArray();
bool refs=removed.Length==1&&removed[0].StartsWith("ExtensibleSaveFormat,")&&added.Any(r=>r.StartsWith("KKS_ExtensibleSaveFormat,"))&&added.All(r=>r.StartsWith("KKS_ExtensibleSaveFormat,")||r.StartsWith("UnityEngine.CoreModule,")||r.StartsWith("UnityEngine.UIModule,"));
int resolved=0;var unresolved=new List<string>();foreach(var r in b.MainModule.GetMemberReferences()){var owner=r.DeclaringType.Scope.Name;if(owner=="mscorlib"||owner.StartsWith("System"))continue;try{var def=r is MethodReference m?(IMemberDefinition)m.Resolve():r is FieldReference f?f.Resolve():null;if(def==null)unresolved.Add(r.FullName);else resolved++;}catch(Exception e){unresolved.Add(r.FullName+": "+e.GetType().Name);}}
var runner=b.MainModule.GetType("CameraFXSlots.CameraFXSlotsRunner");
var leftoverImports=runner.Methods.Where(m=>m.HasBody).SelectMany(m=>m.Body.Instructions).Where(i=>i.Operand is MethodReference mr&&mr.Name.Contains("SceneBeingImported")).Select(i=>i.ToString()).ToArray();
bool pass=scope&&refs&&originalFields.SequenceEqual(newFields)&&resources&&unresolved.Count==0&&leftoverImports.Length==0;
string Hash(string p)=>Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(p))).ToLowerInvariant();
var result=new{passed=pass,originalSha256=Hash(original),candidateSha256=Hash(candidate),originalMethods=old.Count,changedMethods=changed,unchangedOriginalMethods=old.Count-changed.Length,addedHelperMethods=addedMethods,onlyExpectedOriginalMethodsChanged=scope,originalFieldsUnchanged=originalFields.SequenceEqual(newFields),resourcesUnchanged=resources,removedReferences=removed,addedReferences=added,onlyExpectedInstalledReferences=refs,resolvedMembers=resolved,unresolvedMembers=unresolved,leftoverImportSubscriptions=leftoverImports,scope="IL/metadata only; no target execution. Original load/save/material logic remains unchanged; lifecycle helper is embedded, no helper DLL reference. Native camera import contract and actual-CIL tests are separate evidence."};
File.WriteAllText(output,JsonSerializer.Serialize(result,new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine(JsonSerializer.Serialize(result));if(!pass)Environment.ExitCode=1;
